<?php
namespace App\Http\Controllers;
use App\Models\Setting; use App\Models\TahunPelajaran; use App\Models\Kelas; use Illuminate\Http\Request; use Illuminate\Http\RedirectResponse; use Illuminate\Support\Facades\DB; use Inertia\Inertia; use Inertia\Response;
class SettingsController extends Controller { public function index():Response{return Inertia::render('Settings/Index',['settings'=>['teacherName'=>Setting::get('teacher_name','Administrator'),'schoolName'=>Setting::get('school_name','Sekolah Anda'),'teacherPhone'=>Setting::get('teacher_phone',''),'activeYear'=>Setting::get('active_year','2026/2027'),'activeSemester'=>Setting::get('active_semester','ganjil'),'activeClass'=>Setting::get('active_class','Kelas 1')]]);} public function update(Request $request):RedirectResponse{$data=$request->validate(['teacherName'=>['required','string','max:100'],'schoolName'=>['required','string','max:150'],'teacherPhone'=>['nullable','string','max:30'],'activeYear'=>['required','regex:/^\d{4}\/\d{4}$/'],'activeSemester'=>['required','in:ganjil,genap'],'activeClass'=>['required','string','max:50']]); DB::transaction(function() use ($data){ Setting::put('teacher_name',$data['teacherName']); Setting::put('school_name',$data['schoolName']); Setting::put('teacher_phone',$data['teacherPhone'] ?? ''); $year=TahunPelajaran::firstOrCreate(['tahun'=>$data['activeYear'],'semester'=>$data['activeSemester']],['status'=>'nonaktif']); TahunPelajaran::query()->update(['status'=>'nonaktif']); $year->update(['status'=>'aktif']); $kelas=Kelas::firstOrCreate(['nama_kelas'=>$data['activeClass'],'tahun_pelajaran_id'=>$year->id],['tingkat'=>'X']); Setting::put('active_year_id',(string)$year->id); Setting::put('active_class_id',(string)$kelas->id); Setting::put('active_year',$data['activeYear']); Setting::put('active_semester',$data['activeSemester']); Setting::put('active_class',$data['activeClass']); }); return back()->with('success','Pengaturan dan sesi aktif berhasil disimpan. Data sesi sebelumnya tetap menjadi histori.');} }
